select t.slug, string_agg(ss.code, ',' order by ss.code) as codes, (select count(*) from questions q join quizzes z on z.id=q.quiz_id where z.topic_id=t.id and q.difficulty='exam' and q.statement_id is not null) as linked, (select count(*) from flashcards f join flashcard_sets fs on fs.id=f.set_id where fs.topic_id=t.id) as fc, (select length(sm.content) from study_materials sm where sm.topic_id=t.id and sm.material_type='notes' order by length(sm.content) desc limit 1) as notes from topics t join subject_levels sl on sl.id=t.subject_level_id join subjects s on s.id=sl.subject_id left join syllabus_statements ss on ss.topic_id=t.id where s.name ilike '%physics%' and sl.level::text='OL' group by t.id, t.slug order by t.slug;
